var n=`0746-ful-eritrean-style`;var t=`world-0746`;var a=`ER`;var s=`eastern-africa`;var o=4;var r=573;var l={en:`Ful Eritrean Style`,ua:`Фуль по-еритрейськи`};var d={en:`Ful Eritrean Style is a Eritrea classic prepared with fava beans, yellow onion, tomato, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фуль по-еритрейськи, страва кухні країни Еритрея зі складниками: боби фава, жовта цибуля, помідор, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`fava-beans`,300,`g`],[`water`,800,`ml`]]},{en:`Cook soaked fava beans in fresh water until completely tender; mash a portion so the ful becomes naturally creamy.`,ua:`Зваріть замочені боби фава у свіжій воді до повної м’якості; частину розімніть для природної кремовості фуля.`,t:[`boiling`],m:75,i:[[`water`,850,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,190,`g`],[`tomato`,250,`g`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`lemon-juice`,35,`ml`],[`ground-cumin`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var m={slug:n,id:t,country:`ER`,region:s,servings:4,minutes:573,title:l,text:d,steps:u};export{a as country,m as default,t as id,r as minutes,s as region,o as servings,n as slug,u as steps,d as text,l as title};